package com.tanidikvar.api.retention.service;
import com.tanidikvar.api.auth.service.*;import java.util.*;import org.slf4j.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;
@Component public class QuestionOutboxProcessor{private static final Logger log=LoggerFactory.getLogger(QuestionOutboxProcessor.class);private final JdbcTemplate jdbc;private final AuthMailDelivery mail;private final String from;public QuestionOutboxProcessor(JdbcTemplate jdbc,AuthMailDelivery mail,@Value("${app.mail.from}")String from){this.jdbc=jdbc;this.mail=mail;this.from=from;}
 record Delivery(UUID id,String email,String title){}
 @Scheduled(fixedDelayString="${app.notifications.outbox-delay-ms:60000}",initialDelayString="${app.notifications.outbox-initial-delay-ms:30000}")public void process(){try{expand();deliver();}catch(RuntimeException exception){log.warn("notification_outbox_cycle_failed type={} message={}",exception.getClass().getSimpleName(),exception.getMessage());}}
 void expand(){var events=jdbc.query("UPDATE domain_outbox SET attempt_count=attempt_count+1 WHERE id IN (SELECT id FROM domain_outbox WHERE processed_at IS NULL AND event_type='QUESTION_PUBLISHED' ORDER BY created_at,id FOR UPDATE SKIP LOCKED LIMIT 50) RETURNING id,aggregate_id",(r,n)->Map.entry(r.getObject("id",UUID.class),r.getObject("aggregate_id",UUID.class)));for(var event:events){jdbc.update("INSERT INTO outbox_deliveries(id,event_id,user_id,due_at) SELECT md5('email-delivery:'||?::text||':'||candidate.user_id)::uuid,?,candidate.user_id,CASE np.email_frequency WHEN 'WEEKLY' THEN date_trunc('week',CURRENT_TIMESTAMP)+interval '1 week' WHEN 'DAILY' THEN date_trunc('day',CURRENT_TIMESTAMP)+interval '1 day' ELSE CURRENT_TIMESTAMP END FROM (SELECT DISTINCT f.user_id FROM questions q LEFT JOIN university_departments ud ON ud.university_id=q.university_id AND ud.department_id=q.department_id AND ud.deleted_at IS NULL JOIN follows f ON f.deleted_at IS NULL AND ((f.target_type='UNIVERSITY' AND f.target_id=q.university_id) OR (f.target_type='PROGRAM' AND f.target_id=ud.id)) WHERE q.id=? UNION SELECT ev.user_id FROM questions q LEFT JOIN university_departments ud ON ud.university_id=q.university_id AND ud.department_id=q.department_id AND ud.deleted_at IS NULL JOIN education_verifications ev ON ev.verified_at IS NOT NULL AND ev.deleted_at IS NULL AND ev.university_department_id=ud.id WHERE q.id=?) candidate JOIN notification_preferences np ON np.user_id=candidate.user_id JOIN questions q ON q.id=? WHERE candidate.user_id<>q.author_id AND np.email_enabled AND np.question_routing_enabled AND np.email_frequency<>'NEVER' ON CONFLICT DO NOTHING",event.getKey(),event.getKey(),event.getValue(),event.getValue(),event.getValue());jdbc.update("UPDATE domain_outbox SET processed_at=CURRENT_TIMESTAMP,last_error=NULL WHERE id=?",event.getKey());}}
 void deliver(){jdbc.update("UPDATE outbox_deliveries SET status='PENDING',locked_at=NULL WHERE status='PROCESSING' AND locked_at<CURRENT_TIMESTAMP-interval '15 minutes'");var deliveries=jdbc.query("UPDATE outbox_deliveries d SET status='PROCESSING',locked_at=CURRENT_TIMESTAMP,attempt_count=attempt_count+1 WHERE d.id IN (SELECT id FROM outbox_deliveries WHERE status='PENDING' AND due_at<=CURRENT_TIMESTAMP ORDER BY due_at,id FOR UPDATE SKIP LOCKED LIMIT 50) RETURNING d.id,(SELECT u.email FROM users u WHERE u.id=d.user_id),(SELECT q.title FROM domain_outbox o JOIN questions q ON q.id=o.aggregate_id WHERE o.id=d.event_id)",(r,n)->new Delivery(r.getObject(1,UUID.class),r.getString(2),r.getString(3)));for(var delivery:deliveries){try{String text="Deneyimine uygun yeni soru: "+delivery.title()+"\n\nTanıdıkVar hesabından bildirim tercihlerini değiştirebilirsin.";mail.send(new AuthMailMessage(from,delivery.email(),"TanıdıkVar — Deneyimine uygun yeni soru",text,"<p>Deneyimine uygun yeni soru:</p><p><strong>"+escape(delivery.title())+"</strong></p><p>Bildirim tercihlerini hesabından değiştirebilirsin.</p>"));jdbc.update("UPDATE outbox_deliveries SET status='SENT',sent_at=CURRENT_TIMESTAMP,locked_at=NULL,last_error=NULL WHERE id=?",delivery.id());}catch(RuntimeException exception){jdbc.update("UPDATE outbox_deliveries SET status='PENDING',locked_at=NULL,due_at=CURRENT_TIMESTAMP+interval '15 minutes',last_error=? WHERE id=?",exception.getClass().getSimpleName(),delivery.id());}}}
 private String escape(String value){return value.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;");}}
